/* From Uiverse.io by aadium - Tags: radio, futuristic, futuristic-radio-buttons */
.__UIV_SCOPE__ .container input[type="radio"] {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.__UIV_SCOPE__ .container {
  display: inline-block;
  position: relative;
  cursor: pointer;
  font-size: 17px;
  width: 4em;
  height: 4em;
  user-select: none;
  border: 4px solid;
  border-image-slice: 1;
  background-color: #212121;
}

.__UIV_SCOPE__ label {
  font-size: 12px;
  margin-top: -6px;
  font-family: 'Lucida Sans', 'Lucida Sans Regular', 'Lucida Grande', 'Lucida Sans Unicode', Geneva, Verdana, sans-serif;
  text-align: center;
  visibility: visible;
}

.__UIV_SCOPE__ #topleft {
  border-image-source: linear-gradient(-45deg, #743ad5, #d53a9d);
  color: white
}

.__UIV_SCOPE__ #topright {
  border-image-source: linear-gradient(45deg, #743ad5, #d53a9d);
  color: white
}

.__UIV_SCOPE__ #bottomleft {
  border-image-source: linear-gradient(-135deg, #743ad5, #d53a9d);
  color: white
}

.__UIV_SCOPE__ #bottomright {
  border-image-source: linear-gradient(135deg, #743ad5, #d53a9d);
  color: white
}

.__UIV_SCOPE__ .selected {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

.__UIV_SCOPE__ #topleft:hover {
  border-image-source: linear-gradient(-45deg, #743ad5, #d53a9d);
  background-image: linear-gradient(-45deg, #743ad5, #d53a9d);
}

.__UIV_SCOPE__ #topright:hover {
  border-image-source: linear-gradient(45deg, #743ad5, #d53a9d);
  background-image: linear-gradient(45deg, #743ad5, #d53a9d);
}

.__UIV_SCOPE__ #bottomleft:hover {
  border-image-source: linear-gradient(-135deg, #743ad5, #d53a9d);
  background-image: linear-gradient(-135deg, #743ad5, #d53a9d);
}

.__UIV_SCOPE__ #bottomright:hover {
  border-image-source: linear-gradient(135deg, #743ad5, #d53a9d);
  background-image: linear-gradient(135deg, #743ad5, #d53a9d);
}

.__UIV_SCOPE__ #topleft input[type="radio"]:checked ~ .selected {
  box-shadow: 5px 5px 25px #743ad5,
                -5px -5px 25px #d53a9d;
  border-image-slice: 1;
}

.__UIV_SCOPE__ #topright input[type="radio"]:checked ~ .selected {
  box-shadow: -5px 5px 25px #743ad5,
                5px -5px 25px #d53a9d;
  border-image-slice: 1;
}

.__UIV_SCOPE__ #bottomleft input[type="radio"]:checked ~ .selected {
  box-shadow: -5px 5px 25px #d53a9d,
                5px -5px 25px #743ad5;
  border-image-slice: 1;
}

.__UIV_SCOPE__ #bottomright input[type="radio"]:checked ~ .selected {
  box-shadow: -5px -5px 25px #743ad5,
                5px 5px 25px #d53a9d;
  border-image-slice: 1;
}
